-- Without the byte-code cache startup is about 13 ms slower.
vim.loader.enable()

vim.g.mapleader = " "
vim.g.maplocalleader = " "

require("config.keymaps")
require("config.options")
require("config.lsp")

-- Umber (colors/umber.lua) is generated by umber/neovim.py and follows
-- 'background', which Neovim tracks from the terminal. Setting 'background'
-- anywhere in this config stops that tracking. Set before vim.pack.add(),
-- which raises when a plugin fails to install and would skip it.
if not pcall(vim.cmd.colorscheme, "umber") then
	vim.cmd.colorscheme("habamax")
end

-- Rebuild parsers whose revision no longer matches nvim-treesitter's: after an
-- update, and after an install over parsers left by another plugin manager
-- (plugin/treesitter.lua's install() skips languages that exist). With no
-- parsers this is a no-op. update() is async, so wait: a :restart straight
-- after would otherwise kill the builds and leave old parsers under new queries.
vim.api.nvim_create_autocmd("PackChanged", {
	group = vim.api.nvim_create_augroup("pack-hooks", { clear = true }),
	callback = function(ev)
		if ev.data.spec.name == "nvim-treesitter" and (ev.data.kind == "install" or ev.data.kind == "update") then
			if not ev.data.active then
				vim.cmd.packadd("nvim-treesitter")
			end
			local ok, err = require("nvim-treesitter").update(nil, { summary = true }):pwait(300000)
			if err == "timeout" then
				vim.notify(
					"nvim-treesitter parser rebuild still running. Wait for it before :restart",
					vim.log.levels.WARN
				)
			elseif not ok then
				vim.notify(
					"nvim-treesitter parser rebuild failed: " .. tostring(err) .. ". Run :TSUpdate",
					vim.log.levels.ERROR
				)
			end
		end
	end,
})

-- Setup calls live in plugin/<name>.lua. gitsigns and render-markdown set
-- themselves up from their own plugin/ files.
vim.pack.add({
	{ src = "https://github.com/nvim-treesitter/nvim-treesitter", version = "main" },
	{ src = "https://github.com/saghen/blink.cmp", version = vim.version.range("1") },
	"https://github.com/stevearc/conform.nvim",
	"https://github.com/lewis6991/gitsigns.nvim",
	"https://github.com/nvim-tree/nvim-web-devicons",
	"https://github.com/nvim-lualine/lualine.nvim",
	"https://github.com/windwp/nvim-autopairs",
	"https://github.com/MeanderingProgrammer/render-markdown.nvim",
	"https://github.com/ibhagwan/fzf-lua",
})
